import Foundation

/// The sound a person's notifications play.
///
/// Apps may not use the iPhone's ringtones or alert tones, so besides the system default Closer
/// ships its own sounds in the app bundle. They are generated by
/// `scripts/generate-notification-sounds.py`; `fileName` must match the files it writes.
nonisolated enum NotificationSound: String, CaseIterable, Identifiable, Codable {
    /// The iOS default sound for notifications.
    case standard
    case naehe
    case funke
    case tropfen
    case morgen
    case gruss

    var id: String { rawValue }

    var title: String {
        switch self {
        case .standard: "Standard"
        case .naehe: "Nähe"
        case .funke: "Funke"
        case .tropfen: "Tropfen"
        case .morgen: "Morgen"
        case .gruss: "Gruss"
        }
    }

    var subtitle: String {
        switch self {
        case .standard: "Hinweiston des iPhones"
        case .naehe: "Zwei Töne, die sich finden"
        case .funke: "Hell und lebhaft"
        case .tropfen: "Kurz und leise"
        case .morgen: "Ruhig aufsteigend"
        case .gruss: "Ein freundliches Hallo"
        }
    }

    /// File in the app bundle, `nil` for the system default.
    var fileName: String? {
        self == .standard ? nil : "closer-\(rawValue).wav"
    }

    /// Closer's own sounds, without the system default.
    static var bundled: [NotificationSound] { allCases.filter { $0 != .standard } }

    /// Unknown values (e.g. a sound removed in a later version) fall back to `.standard`, so a
    /// person is never lost over their sound.
    init(from decoder: any Decoder) throws {
        let rawValue = try decoder.singleValueContainer().decode(String.self)
        self = NotificationSound(rawValue: rawValue) ?? .standard
    }
}
